import { StringColumn, IntegerColumn, BooleanColumn } from '@servicenow/sdk/core'
import { Subflow, wfa, action } from '@servicenow/sdk/automation'

/**
 * Test subflow for AssignSubflowOutputs with complex inline scripts and datapills
 * Tests that inline scripts and datapills work together without interference
 */
export const assignSubflowOutputsInlineScriptComplex = Subflow(
    {
        $id: Now.ID['assign-subflow-outputs-inline-script-complex'],
        name: 'AssignSubflowOutputs Inline Script Complex Test',
        description: 'Test AssignSubflowOutputs with mix of inline scripts, datapills, and literals',
        inputs: {
            inputNumber: StringColumn({
                label: 'Input Number',
                mandatory: true,
            }),
            inputPriority: IntegerColumn({
                label: 'Input Priority',
                mandatory: false,
            }),
        },
        outputs: {
            // Datapill output
            recordId: StringColumn({
                label: 'Record ID',
                mandatory: true,
            }),
            // Inline script output
            processedData: StringColumn({
                label: 'Processed Data',
                mandatory: true,
            }),
            // Literal output
            status: StringColumn({
                label: 'Status',
                mandatory: true,
            }),
            // Inline script with fd_data
            enrichedInfo: StringColumn({
                label: 'Enriched Info',
                mandatory: true,
            }),
            // Mixed - template with datapill
            summary: StringColumn({
                label: 'Summary',
                mandatory: false,
            }),
            // Inline script returning number
            computedValue: IntegerColumn({
                label: 'Computed Value',
                mandatory: false,
            }),
            // Inline script returning boolean
            isSuccess: BooleanColumn({
                label: 'Is Success',
                mandatory: false,
            }),
        },
    },
    (params) => {
        // Execute an action to get outputs
        const lookupResult = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup-for-subflow-outputs'],
                annotation: 'Look up record for outputs',
            },
            {
                table: 'incident',
                conditions: wfa.dataPill(params.inputs.inputNumber, 'string'),
            }
        )

        // Test: AssignSubflowOutputs with mixed inline scripts, datapills, and literals
        wfa.flowLogic.assignSubflowOutputs(
            {
                $id: Now.ID['assign-outputs-mixed-values'],
                annotation: 'Assign outputs with mixed value types',
            },
            params.outputs,
            {
                // Pure datapill - should be converted to {{<action-uuid>.Record}}
                recordId: wfa.dataPill(lookupResult.Record, 'reference'),

                // Pure inline script - should have scriptActive: true
                processedData: wfa.inlineScript("return 'Processed at: ' + new Date().toISOString()"),

                // Pure literal - should remain as string
                status: 'completed',

                // Inline script accessing fd_data (subflow inputs)
                enrichedInfo: wfa.inlineScript(
                    "return 'Input was: ' + fd_data.subflow_inputs.inputNumber + ' with priority: ' + (fd_data.subflow_inputs.inputPriority || 'N/A')"
                ),

                // Template expression with datapill
                summary: `Processed record ${wfa.dataPill(lookupResult.Record, 'reference')} successfully`,

                // Inline script returning number
                computedValue: wfa.inlineScript('return Math.floor(Math.random() * 1000)'),

                // Inline script returning boolean
                isSuccess: wfa.inlineScript('return true'),
            }
        )
    }
)
